//! tu::grtdonkey against the C TU compiled natively with shipping contraction (state oracle:
//! gen/turef/tu_grtdonkey_ref.c, data tests/data/tu_grtdonkey.txt; regenerate with
//! `python rust/melee_world/gen/turef/tu_shard585.py grtdonkey`). Generated by gen_target_stage.py.
#![allow(static_mut_refs, non_snake_case, unused)]
mod common;
use common::gr::*;
use common::*;
use melee_types::*;
use melee_world::tu::grtdonkey as t;
use melee_world::tu_ext as ext;

include!("stubs/grtdonkey.rs");

unsafe fn state() {
    out(&format!("rs {}\n", ORS));
    out(&format!("si {} {}\n", ext::stage_info.unk8C.b4(), ext::stage_info.unk8C.b5()));
    dump_arena();
    state_end();
}

macro_rules! fnr {
    ($($p:path),* $(,)?) => { $( fnreg(stringify!($p).rsplit("::").next().unwrap(), $p as usize); )* };
}

#[test]
fn matches_c() {
    unsafe {
        reset_all();
        gen_stubs::install();
        install_custom();
        size_t::<Ground>("Ground");
        size_t::<HSD_GObj>("HSD_GObj");
        size_t::<HSD_JObj>("HSD_JObj");
        size_t::<StageCallbacks>("StageCallbacks");
        size_t::<StageData>("StageData");
        reg("cb", t::grTDk_StageCallbacks.as_ptr(), core::mem::size_of_val(&t::grTDk_StageCallbacks));
        reg("sd", &t::grTDk_StageData, core::mem::size_of::<StageData>());
        reg("dat", t::grTDk_StageData.data1, 16);
        fnr!(t::grTDonkey_80220228, t::grTDonkey_OnInit, t::grTdonkey_UnkStage0_OnLoad, t::grTdonkey_UnkStage0_OnStart, t::grTDonkey_802202C4, t::grTDonkey_802202CC, t::grTDonkey_802204FC, t::grTDonkey_80220504, t::stageGObj0_OnInit, t::grTDonkey_802203E0, t::grTDonkey_802203E8, t::grTDonkey_802203EC, t::stageGObj1_OnInit, t::grTDonkey_802204D0, t::stageGObj1_GObjProc, t::grTDonkey_802204F8, t::stageGObj2_OnInit, t::grTDonkey_80220440, t::stageGObj2_GObjProc, t::grTDonkey_8022047C);
        fnreg("grDisplay_801C5DB0", ext::grDisplay_801C5DB0 as usize);
        dump_t("cb", &t::grTDk_StageCallbacks);
        dump_t("sd", &t::grTDk_StageData);
        state_end();

        for c in 0..60usize {
            case(c);
            rseed(100 + c as u32);
            gr_reset();
            ext::stage_info.unk8C.set_b4((rnd() & 1) as u8);
            ext::stage_info.unk8C.set_b5((rnd() & 1) as u8);
            out("r");
            trp(t::grTDonkey_802202CC((c % 3) as i32) as *const u8);
            out("\n");
            state();
        }
        for c in 0..20usize {
            case(1000 + c);
            rseed(2000 + c as u32);
            gr_reset();
            t::grTDonkey_OnInit();
            state();
            t::grTdonkey_UnkStage0_OnStart();
            t::grTdonkey_UnkStage0_OnLoad();
            t::grTDonkey_80220228(rnd() as i32);
            state();
        }
        for c in 0..12usize {
            case(2000 + c);
            rseed(3000 + c as u32);
            gr_reset();
            let g = mkgobj();
            t::stageGObj0_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTDonkey_802203E0(g)));
            t::grTDonkey_802203E8(g);
            t::grTDonkey_802203EC(g);
            state();
            t::stageGObj1_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTDonkey_802204D0(g)));
            t::stageGObj1_GObjProc(g);
            t::grTDonkey_802204F8(g);
            state();
            t::stageGObj2_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTDonkey_80220440(g)));
            t::stageGObj2_GObjProc(g);
            t::grTDonkey_8022047C(g);
            state();
            out(&format!("r {}\n", t::grTDonkey_802202C4()));
            out("r");
            trp(t::grTDonkey_802204FC(rnd() as i32) as *const u8);
            out("\n");
            let mut v = Vec3 { x: rf(), y: rf(), z: rf() };
            let a1 = rnd() as i32;
            let j = mkjobj();
            out(&format!("r {}\n", t::grTDonkey_80220504(&mut v, a1, j)));
            state();
        }
    }
    check("tu_grtdonkey");
}
